review2/coverage/rows.py:229: ('§76.6', 'newArena: WF3, I1, AnchorOrder, AnchorOrderHeld, arena invariants', [(76,6)], 'F', 'newArena_clause6 (redundant)'),
import json,ast,sys
sys.path.insert(0,'.')
from rows import ROWS
idx={ast.literal_eval(k):v for k,v in json.load(open('index.json')).items()}
pri={'structure':0,'inductive':0,'class':0,'def':1,'abbrev':1,'field':2,'theorem':3,'instance':5}
def decls(keys):
    seen=[];corp=0
    for k in keys:
        for mod,n,kind in idx.get(k,[]):
            if 'Corpus' in mod: corp+=1; continue
            if (n,kind) not in [(a,b) for a,b in seen]: seen.append((n,kind))
    seen.sort(key=lambda x:pri.get(x[1],4))
    shown=[f"`{n}`" for n,k in seen if k!='instance'][:7]
    more=len(seen)-len(shown)
    s=', '.join(shown)+(f' (+{more})' if more>0 else '')
    if corp: s+=f' [corpus: {corp}]'
    return s or '—'
lab={'F':'formalized','R':'realized, uncited','REC':'NONE, reason recorded','NC':'NONE, no content, unrecorded','MISS':'NONE, unrecorded'}
out=['# Coverage table: spec v0 §8–§82 → declarations (model + library modules)','',
 'Generated by `extract.py` (declarations and docstring citations of `formal/Ern/MemoryModel/**`, `formal/Ern/Lib/*`, `formal/Ern/Corpus/*`) and `cover.py`/`gen.py` (index by clause). The declarations column lists up to 7 non-instance declarations whose docstring cites the clause (structures/defs first), the count of the others, and corpus citations separately. Statuses: formalized = a model/lib declaration cites and encodes it; realized, uncited = encoded by declarations citing other clauses (named in the note); NONE = no declaration, with whether a reason is recorded (readings/, reports/, review1-dispositions, policy) and the finding id (M = major, C = minor) when not.','',
 '| Clause | Content | Declarations (docstring cites the clause) | Status | Note |','|---|---|---|---|---|']
cnt={}
for cid,txt,keys,st,note in ROWS:
    cnt[st]=cnt.get(st,0)+1
    out.append(f"| {cid} | {txt} | {decls(keys)} | {lab[st]} | {note} |")
out+=['',f"Rows: {len(ROWS)}; "+', '.join(f'{lab[k]}: {v}' for k,v in cnt.items())]
open('table.md','w').write('\n'.join(out)+'\n')
print(cnt, len(ROWS))
"""Citation index: clause key -> declarations whose docstring cites it (current tree).
Usage: index.py DECLS.json OUT.json. Keys: 'N' (bare §N), 'N.k' (item), 'N ¶p' (paragraph), 'N~' (inside a §N–§M range)."""
import json, re, sys, collections
D = '[–-]'
def cites(doc):
    out = set()
    doc = re.sub(r'material\s+§\d+[a-z]?', ' ', doc)  # sections of the attached corpus material, not of the spec
    for m in re.finditer(r'§(\d+)\s*' + D + r'\s*§(\d+)(?!\d)(?!\.\d)', doc):
        for k in range(int(m.group(1)), int(m.group(2)) + 1): out.add('%d~' % k)
    doc = re.sub(r'§(\d+)\s*' + D + r'\s*§(\d+)(?!\d)(?!\.\d)', ' ', doc)
    for m in re.finditer(r'§(\d+)\.(\d+)[a-z]?\s*' + D + r'\s*§?(\d+)(?:\.(\d+))?', doc):
        a, i, b, j = m.groups()
        if j is None: out.update('%s.%d' % (a, k) for k in range(int(i), int(b) + 1))
        elif a == b: out.update('%s.%d' % (a, k) for k in range(int(i), int(j) + 1))
        else: out.update(('%s.%s' % (a, i), '%s.%s' % (b, j)))
    for m in re.finditer(r'§(\d+)(?:\s*,\s*|\s*\(\s*)(?:items?|cases?)\s+(\d+)(?:\s*' + D + r'\s*(\d+))?', doc):
        a, i, j = int(m.group(1)), int(m.group(2)), m.group(3)
        out.update('%d.%d' % (a, k) for k in range(i, (int(j) if j else i) + 1))
    for m in re.finditer(r'§(\d+)\.(\d+)', doc): out.add('%s.%s' % m.groups())
    for m in re.finditer(r'§(\d+)\s+¶(\d+)(?:\s*' + D + r'\s*¶?(\d+))?', doc):
        a, i, j = int(m.group(1)), int(m.group(2)), m.group(3)
        out.update('%d ¶%d' % (a, k) for k in range(i, (int(j) if j else i) + 1))
    for m in re.finditer(r'§(\d+)(?!\d)(?!\.\d)', doc): out.add(m.group(1))
    return out
idx = collections.defaultdict(list)
nocite = []
for r in json.load(open(sys.argv[1])):
    if r['kind'] == 'example': continue
    c = cites(r['doc'])
    mod = r['file'][len('Ern/'):-len('.lean')].replace('/', '.')
    short = r['name'].replace('Ern.MemoryModel.', '').replace('Ern.Lib.', 'Lib.').replace('Ern.Corpus.', 'Corpus.')
    if not c and r['kind'] != 'instance': nocite.append((mod, short, r['kind'], r['line']))
    for k in c: idx[k].append(dict(mod=mod, name=short, kind=r['kind'], file=r['file'], line=r['line']))
json.dump(dict(index=idx, nocite=nocite), open(sys.argv[2], 'w'), ensure_ascii=False)
print(len(idx), 'keys;', len(nocite), 'declarations without a § citation')
"""Report defs/structures/inductives whose full text (declaration line to the next declaration or docstring) changed.
Usage: bodies.py OLD.json OLD_ROOT NEW.json NEW_ROOT"""
import json, sys
def texts(p, root):
    rows = [r for r in json.load(open(p)) if r['kind'] in ('def', 'structure', 'inductive', 'abbrev')]
    byfile = {}
    for r in json.load(open(p)):
        byfile.setdefault(r['file'], []).append(r['line'])
    out = {}
    for r in rows:
        lines = open(f"{root}/{r['file']}").read().split('\n')
        nxt = min([l for l in byfile[r['file']] if l > r['line']], default=len(lines) + 1)
        body = [t for t in lines[r['line'] - 1:nxt - 1] if not t.strip().startswith('--')]
        # drop a trailing docstring of the next declaration
        txt = '\n'.join(body)
        cut = min([k for k in (txt.find('/--'), txt.find('/-!')) if k >= 0], default=-1)
        out[(r['name'], r['kind'])] = ' '.join((txt[:cut] if cut >= 0 else txt).split())
    return out
a, b = texts(sys.argv[1], sys.argv[2]), texts(sys.argv[3], sys.argv[4])
for k in sorted(set(a) & set(b)):
    if a[k] != b[k]: print('BODY', k[1], k[0], sep='\t')
